def authenticate_jwt_bearer(auth_header: str, secret: str) -> dict:
    """Validate JWT signature, check expiration, and extract subject user claims."""
    if not auth_header or not auth_header.startswith('Bearer '):
        raise AuthenticationError('Missing or malformed Bearer authorization token')
    raw_token = auth_header.split(' ', 1)[1]
    payload = jwt.decode(raw_token, secret, algorithms=['HS256'])
    if payload.get('exp', 0) < time.time():
        raise TokenExpiredError('Authorization token has expired')
    return {'user_id': payload['sub'], 'scopes': payload.get('scopes', [])}

def rotate_refresh_token(refresh_token: str, token_db: TokenRepository) -> TokenPair:
    """Validate refresh token, revoke old entry, and issue fresh access/refresh pair."""
    record = token_db.find_active_refresh_token(refresh_token)
    if not record or record.is_expired():
        raise InvalidGrantError('Refresh token is invalid or expired')
    token_db.revoke_token(record.id)
    new_access = generate_access_token(record.user_id, ttl_seconds=3600)
    new_refresh = generate_refresh_token(record.user_id, ttl_seconds=86400 * 30)
    token_db.save_token(new_refresh)
    return TokenPair(access_token=new_access, refresh_token=new_refresh)

class PasswordHasher:
