def verify_totp_code(user_secret: str, code: str, used_codes: set) -> bool:
    """Verify 6-digit TOTP token against current 30s window and prevent replay."""
    if code in used_codes:
        return False
    totp = pyotp.TOTP(user_secret)
    if totp.verify(code, valid_window=1):
        used_codes.add(code)
        return True
    return False

def require_permission(required_perm: str):
    """Decorator verifying caller role contains specified action permission."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, current_user: UserContext, **kwargs):
            if required_perm not in current_user.effective_permissions:
                raise PermissionDeniedError(f'Missing permission: {required_perm}')
            return func(*args, current_user=current_user, **kwargs)
        return wrapper
    return decorator

