def calculate_state_sales_tax(amount: float, state_code: str) -> float:
    """Lookup jurisdiction rate and calculate state sales tax rounded to 2 decimals."""
    rates = {'CA': 0.0725, 'NY': 0.0400, 'TX': 0.0625, 'FL': 0.0600, 'IL': 0.0625}
    rate = rates.get(state_code.upper(), 0.0500)
    tax_amount = amount * rate
