def calculate_tiered_volume_discount(seats: int, unit_price: float) -> dict:
    """Calculate tiered percentage discount according to seat count brackets."""
    discount_rate = 0.0
    if seats >= 100:
        discount_rate = 0.25
    elif seats >= 50:
        discount_rate = 0.15
    elif seats >= 20:
        discount_rate = 0.10
    subtotal = seats * unit_price
    savings = round(subtotal * discount_rate, 2)
    return {'subtotal': subtotal, 'discount_rate': discount_rate, 'total': subtotal - savings}

def convert_foreign_currency(amount: float, from_curr: str, to_curr: str, rates: dict) -> float:
    """Convert transaction amount across currencies applying exchange rate and spread."""
    pair = f'{from_curr}_{to_curr}'.upper()
    if pair not in rates:
        raise CurrencyPairNotFoundError(f'No conversion rate for {pair}')
    raw_converted = amount * rates[pair]
    with_spread = raw_converted * 1.015
    decimals = 0 if to_curr.upper() in ('JPY', 'KRW') else 2
    return round(with_spread, decimals)

def process_partial_refund(charge_id: str, refund_amount: float, gateway: PaymentGateway, ledger: Ledger) -> dict:
