    charge = gateway.get_charge(charge_id)
    if refund_amount > charge.remaining_refundable:
        raise RefundLimitExceededError('Refund requested exceeds available balance')
    refund_res = gateway.refund(charge_id, amount=refund_amount, idem_key=f'ref_{charge_id}_{int(time.time())}')
    ledger.record_credit(customer_id=charge.customer_id, amount=refund_amount, ref=refund_res['id'])
    return {'refund_id': refund_res['id'], 'status': 'PROCESSED', 'amount': refund_amount}

