def atomic_transaction(conn: Connection):
    """Context manager ensuring database transaction commits on success or rolls back on exception."""
    conn.autocommit = False
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.autocommit = True

