class ResilientConnectionPool:
    """Manages database connections, verifying connection health before checkout."""
    def __init__(self, dsn: str, min_size: int = 5, max_size: int = 20):
        self.pool = Queue(maxsize=max_size)
        self.dsn = dsn
    def acquire(self) -> Connection:
        conn = self.pool.get(timeout=5.0)
        if not self._is_alive(conn):
            conn.close()
            conn = self._create_connection()
        return conn
    def _is_alive(self, conn: Connection) -> bool:
        try:
            return conn.ping()
        except Exception:
            return False

class ReplicationRouter:
    """Routes read SELECT operations to replicas and mutations to primary master."""
    def __init__(self, master_conn: Connection, replica_conns: list[Connection]):
        self.master = master_conn
        self.replicas = replica_conns
        self.idx = 0
    def route_query(self, sql_query: str) -> Connection:
        clean = sql_query.strip().upper()
        if clean.startswith('SELECT') and not clean.endswith('FOR UPDATE'):
            chosen = self.replicas[self.idx % len(self.replicas)]
            self.idx += 1
            return chosen
        return self.master

class DistributedRedisLock:
    """Distributed mutex lock with automatic TTL expiration and safe Lua unlock."""
    LUA_UNLOCK = """
    if redis.call('get', KEYS[1]) == ARGV[1] then
        return redis.call('del', KEYS[1])
    else
        return 0
    end
    """
    def __init__(self, redis_client: Redis, lock_name: str, ttl: int = 10):
        self.redis = redis_client
        self.key = f'lock:{lock_name}'
        self.ttl = ttl
        self.token = str(uuid.uuid4())
    def acquire(self) -> bool:
        return bool(self.redis.set(self.key, self.token, nx=True, ex=self.ttl))
    def release(self) -> bool:
        return bool(self.redis.eval(self.LUA_UNLOCK, 1, self.key, self.token))

class LRUCache:
    """In-memory least recently used cache supporting O(1) get and put operations."""
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()
    def get(self, key: str) -> Any:
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key: str, value: Any) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

class TaggedCacheManager:
    """Manages cache invalidation using tagged entity relationships in Redis."""
    def __init__(self, redis: Redis):
        self.redis = redis
    def set_tagged(self, key: str, value: Any, tags: list[str], ttl: int = 3600) -> None:
        self.redis.set(key, json.dumps(value), ex=ttl)
        for tag in tags:
            self.redis.sadd(f'tag:{tag}', key)
    def invalidate_tag(self, tag: str) -> int:
        keys = self.redis.smembers(f'tag:{tag}')
        if not keys:
            return 0
        deleted = self.redis.delete(*keys)
        self.redis.delete(f'tag:{tag}')
        return deleted

class ConsistentHashRing:
    """Consistent hash ring distributing keys across server nodes using virtual replicas."""
    def __init__(self, nodes: list[str], replicas: int = 100):
        self.replicas = replicas
        self.ring = dict()
        self.sorted_keys = []
        for node in nodes:
            self.add_node(node)
    def add_node(self, node: str) -> None:
        for i in range(self.replicas):
            val = int(hashlib.md5(f'{node}:{i}'.encode()).hexdigest(), 16)
            self.ring[val] = node
            self.sorted_keys.append(val)
        self.sorted_keys.sort()
    def get_node(self, key: str) -> str:
        val = int(hashlib.md5(key.encode()).hexdigest(), 16)
        idx = bisect.bisect_right(self.sorted_keys, val) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

class WebSocketRoomManager:
    """Broadcasts JSON messages to active room WebSocket client connections."""
    def __init__(self):
        self.rooms: dict[str, set[WebSocket]] = defaultdict(set)
    async def broadcast_to_room(self, room_id: str, payload: dict) -> int:
        subscribers = self.rooms[room_id]
        sent_count = 0
        for ws in list(subscribers):
            try:
                await ws.send_json(payload)
                sent_count += 1
            except WebSocketDisconnect:
                subscribers.discard(ws)
        return sent_count

