def verify_webhook_signature(raw_body: bytes, header_sig: str, secret_key: str) -> bool:
    """Validate inbound webhook HMAC-SHA256 signature against timing attacks."""
    if not header_sig or not raw_body:
        return False
    expected = hmac.new(secret_key.encode('utf-8'), raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, header_sig)

def request_with_exponential_backoff(url: str, max_retries: int = 4, base_delay: float = 0.5) -> requests.Response:
    """Execute HTTP GET request retrying transient 5xx errors with exponential jitter."""
    for attempt in range(max_retries):
        try:
            resp = requests.get(url, timeout=3.0)
            if resp.status_code < 500:
                return resp
        except (requests.Timeout, requests.ConnectionError):
            if attempt == max_retries - 1:
                raise
        delay = base_delay * (2 ** attempt) + random.uniform(0, 0.2)
        time.sleep(delay)
    raise MaxRetriesExceededError(f'Failed to fetch {url} after {max_retries} attempts')

class CircuitBreaker:
    """Circuit breaker failing fast during remote dependency outages."""
    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0):
        self.threshold = failure_threshold
        self.timeout = recovery_timeout
        self.failure_count = 0
        self.state = 'CLOSED'
        self.last_failure_time = 0.0
    def call(self, func: Callable, *args, **kwargs) -> Any:
        if self.state == 'OPEN':
            if time.time() - self.last_failure_time > self.timeout:
                self.state = 'HALF-OPEN'
            else:
                raise CircuitBreakerOpenError('Remote dependency is currently offline')
        try:
            result = func(*args, **kwargs)
            self.state = 'CLOSED'
            self.failure_count = 0
            return result
        except Exception:
            self.failure_count += 1
            self.last_failure_time = time.time()
            if self.failure_count >= self.threshold:
                self.state = 'OPEN'
            raise

class TenantConcurrencyLimiter:
    """Limits concurrent job execution count per tenant using async semaphores."""
    def __init__(self, max_concurrent: int = 3):
        self.semaphores: dict[str, asyncio.Semaphore] = {}
        self.max = max_concurrent
    @asynccontextmanager
    async def acquire_slot(self, tenant_id: str):
        if tenant_id not in self.semaphores:
            self.semaphores[tenant_id] = asyncio.Semaphore(self.max)
        sem = self.semaphores[tenant_id]
        await sem.acquire()
        try:
            yield
        finally:
            sem.release()

