class KeyRing:
    """Manages multiple symmetric keys, supporting key rotation and legacy decryption."""
    def __init__(self, primary_version: str, keys: dict[str, bytes]):
        self.primary = primary_version
        self.keys = keys
    def encrypt(self, data: bytes) -> tuple[str, bytes]:
        active_key = self.keys[self.primary]
        ciphertext = encrypt_aes(data, active_key)
        return self.primary, ciphertext
    def decrypt(self, version: str, ciphertext: bytes) -> bytes:
