def create_directory_zip_archive(src_dir: Path, target_zip: Path) -> int:
    """Recursively pack source directory into Deflate-compressed ZIP archive."""
    with zipfile.ZipFile(target_zip, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        for file_path in src_dir.rglob('*'):
            if file_path.is_file():
                arcname = file_path.relative_to(src_dir)
                zf.write(file_path, arcname=arcname)
    return target_zip.stat().st_size

def consume_kafka_batch(consumer: KafkaConsumer, handler: Callable, max_records: int = 50) -> int:
    """Poll batch of Kafka records, execute handler, and commit offsets on success."""
    msg_pack = consumer.poll(timeout_ms=1000, max_records=max_records)
    processed = 0
    for topic_partition, messages in msg_pack.items():
        for msg in messages:
            handler(json.loads(msg.value.decode('utf-8')))
            processed += 1
    consumer.commit()
    return processed

