def execute_idempotent_task(idem_key: str, task_func: Callable, redis: Redis) -> Any:
    """Ensure task runs exactly once for a given idempotency key using Redis locking."""
    key = f'idem:{idem_key}'
    if not redis.set(key, 'IN_PROGRESS', nx=True, ex=86400):
        logger.info('Duplicate task ignored for key %s', idem_key)
        return None
    try:
        result = task_func()
        redis.set(key, 'COMPLETED', ex=86400)
        return result
    except Exception:
        redis.delete(key)
        raise

