def extract_ast_function_signatures(source_code: str) -> list[dict]:
    """Parse Python source code AST to extract function names, docstrings, and line ranges."""
    tree = ast.parse(source_code)
    functions = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            doc = ast.get_docstring(node) or ''
            args = [a.arg for a in node.args.args]
            functions.append({
                'name': node.name,
                'args': args,
                'docstring': doc.strip(),
                'line_start': node.lineno,
                'line_end': getattr(node, 'end_lineno', node.lineno)
            })
    return functions

def parse_git_diff_patch(diff_text: str) -> list[dict]:
    """Parse git patch text extracting modified file paths and changed line spans."""
    patches = []
    curr_file = None
    curr_hunks = []
    for line in diff_text.splitlines():
        if line.startswith('+++ b/'):
            if curr_file:
                patches.append({'file': curr_file, 'hunks': curr_hunks})
            curr_file = line[6:].strip()
            curr_hunks = []
        elif line.startswith('@@') and curr_file:
            match = re.search(r'\+(\d+)(?:,(\d+))?', line)
            if match:
                start = int(match.group(1))
                count = int(match.group(2)) if match.group(2) else 1
                curr_hunks.append((start, start + count - 1))
    if curr_file:
        patches.append({'file': curr_file, 'hunks': curr_hunks})
    return patches

