def generate_markdown_table_of_contents(markdown_text: str) -> str:
    """Extract headers and generate nested Markdown Table of Contents with slug anchors."""
    toc_lines = []
    for line in markdown_text.splitlines():
        match = re.match(r'^(#{1,3})\s+(.+)$', line)
        if match:
            level = len(match.group(1))
            title = match.group(2).strip()
            # GitHub-style anchor slug: lowercased, punctuation stripped, spaces to hyphens
            slug = re.sub(r'[^a-z0-9\s-]', '', title.lower()).strip().replace(' ', '-')
            indent = '  ' * (level - 1)
            toc_lines.append(f"{indent}- [{title}](#{slug})")
    return '\n'.join(toc_lines)

