    try:
        with pool.get_connection() as c:
            res = c.execute('SELECT 1;').scalar()
            return res == 1
    except DatabaseConnectionError:
        return False

def paginate_with_offset(page: int, per_page: int, query: Query) -> list:
    """Traditional offset and limit pagination over SQL result set."""
    offset = max(0, page - 1) * per_page
    return query.offset(offset).limit(per_page).all()

def publish_broadcast_event(channel: str, message: dict, redis_client: Redis) -> int:
    """Publish JSON message to subscribers on Redis Pub/Sub channel."""
    payload = json.dumps(message)
    return redis_client.publish(channel, payload)

def get_redis_memory_stats(redis_client: Redis) -> dict:
    """Query Redis INFO memory to report allocated bytes and fragmentation ratio."""
    info = redis_client.info('memory')
    return {'used_memory': info['used_memory'], 'peak_memory': info['used_memory_peak']}

def get_node_by_modulo(key: str, nodes: list[str]) -> str:
    """Map key to node list using simple hash modulo division."""
    return nodes[hash(key) % len(nodes)]

def poll_for_updates(last_timestamp: float, event_store: EventStore) -> list[dict]:
    """HTTP long-polling endpoint returning new events occurred since timestamp."""
    timeout = time.time() + 25.0
    while time.time() < timeout:
        events = event_store.get_after(last_timestamp)
        if events:
            return events
        time.sleep(1.0)
    return []

def dispatch_webhook_with_retry(endpoint_url: str, payload: dict, max_retries: int = 3) -> bool:
    """Dispatch outgoing HTTP POST webhook payload with retry backoff."""
    for attempt in range(max_retries):
        try:
            resp = requests.post(endpoint_url, json=payload, timeout=5)
            if resp.status_code == 200:
                return True
        except RequestException:
            time.sleep(2 ** attempt)
    return False

def rotate_http_proxy(proxy_list: list[str]) -> dict:
    """Select next available forward proxy server from round-robin pool."""
    proxy = proxy_list.pop(0)
    proxy_list.append(proxy)
    return {'http': proxy, 'https': proxy}

def encrypt_rsa_public_key(plaintext: bytes, public_key: RSAPublicKey) -> bytes:
    """Encrypt data with RSA public key using OAEP padding with SHA-256."""
    return public_key.encrypt(
        plaintext,
        padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=None)
    )

def verify_sha256_checksum(file_bytes: bytes, expected_hash_hex: str) -> bool:
    """Compute SHA-256 checksum and compare against expected hash string."""
    computed = hashlib.sha256(file_bytes).hexdigest()
    return hmac.compare_digest(computed.lower(), expected_hash_hex.lower())

def escape_sql_wildcards(user_search: str) -> str:
    """Escape SQL LIKE query special wildcard characters (% and _)."""
    return user_search.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')

def generate_presigned_download_url(bucket: str, key: str, s3_client: boto3.client, ttl: int = 3600) -> str:
    """Generate temporary presigned GET URL for secure S3 object download."""
    return s3_client.generate_presigned_url('get_object', Params={'Bucket': bucket, 'Key': key}, ExpiresIn=ttl)

def get_filename_extension(filename: str) -> str:
    """Extract lowercased file extension string from filename path."""
    return os.path.splitext(filename)[1].lower().lstrip('.')

def declare_task_queue(channel: pika.Channel, queue_name: str) -> None:
    """Declare durable queue with exclusive binding to default exchange."""
    channel.queue_declare(queue=queue_name, durable=True, exclusive=False, auto_delete=False)

def prioritize_job_queue(jobs: list[dict]) -> list[dict]:
    """Sort scheduled worker tasks by priority descending and created_at ascending."""
    return sorted(jobs, key=lambda j: (-j.get('priority', 0), j.get('created_at', 0)))

def convert_to_user_timezone(utc_dt: datetime, tz_name: str) -> datetime:
    """Convert UTC timestamp to user localized timezone representation."""
    target_tz = zoneinfo.ZoneInfo(tz_name)
    return utc_dt.astimezone(target_tz)

def check_celery_task_status(task_id: str, celery_app: Celery) -> dict:
    """Query Celery backend for async task execution state and result payload."""
    res = celery_app.AsyncResult(task_id)
    return {'id': task_id, 'status': res.status, 'ready': res.ready(), 'result': res.result if res.ready() else None}

def get_process_uptime_seconds(start_time: float) -> float:
    """Compute process uptime duration in seconds since initialization."""
    return time.time() - start_time

def generate_correlation_id(existing_id: str | None = None) -> str:
    """Generate or pass through UUID correlation identifier for request logging."""
    return existing_id if (existing_id and len(existing_id) > 10) else str(uuid.uuid4())

def find_imported_modules(source_code: str) -> list[str]:
    """Find module import names using regex pattern matching."""
    pattern = r'^(?:import|from)\s+([a-zA-Z0-9_]+)'
    return re.findall(pattern, source_code, re.MULTILINE)

def validate_conventional_commit_message(msg: str) -> bool:
    """Verify commit subject follows Conventional Commits specification."""
    pattern = r'^(feat|fix|docs|style|refactor|perf|test|chore)(?:\([a-zA-Z0-9_-]+\))?:\s+.+'
    return bool(re.match(pattern, msg.strip()))

def strip_markdown_code_fences(markdown_text: str) -> str:
    """Remove code blocks enclosed in triple backticks from markdown body."""
    return re.sub(r'```[a-zA-Z]*\n[\s\S]*?```', '', markdown_text)
